    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.stride = 4
        self.padding = 2
        self.kernel_size = 11
        self.in_channels = 3
        self.out_channels = 96
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size))
        self.bias = nn.Parameter(torch.empty(self.out_channels))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)
        self.conv2d_forward = conv2d_module.conv2d_forward
    def forward(self, x):
        x = x.cuda().contiguous()
        return self.conv2d_forward(x, self.weight, self.bias, self.stride, self.padding)

